/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Validate a todo_add request. B1: optional owner (must be an active entry
   in the people directory). Empty owner = the owner's own todo.
   A: optional project. Like owner, it must already exist in the projects
   registry, so a typo cannot silently start a parallel project. */
const body = ($('Webhook Add').first().json.body) || {};
const text = String(body.text || '').trim().slice(0, 300);
const bad = (m, c) => [{ json: { __error: true, status: 400, body: { error: { message: m, type: 'invalid_request_error', code: c } } } }];
if (!text) return bad('text is required', 'missing_text');
let due = '';
if (body.due_date) {
  const t = Date.parse(String(body.due_date));
  if (!Number.isFinite(t)) return bad('due_date must be a date like 2026-09-18', 'bad_due_date');
  due = new Date(t).toISOString().slice(0, 10);
}
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const pid = (tables.find((t) => t.name === 'people') || {}).id;
let owner_ref = '';
const ownerRaw = String(body.owner || body.owner_ref || '').trim().replace(/^@/, '');
if (ownerRaw) {
  if (!pid) return bad('people table missing (run deploy.mjs)', 'no_people_table');
  const prows = (await api('GET', '/data-tables/' + pid + '/rows', { limit: 200 })).data || [];
  const person = prows.find((p) => p.name === ownerRaw);
  if (!person) return bad('unknown person: ' + ownerRaw + ' — add them on the console People page first', 'unknown_person');
  if (!(person.active === 1 || person.active === true)) return bad('person is inactive: ' + ownerRaw, 'person_inactive');
  owner_ref = person.name;
}
const prjid = (tables.find((t) => t.name === 'projects') || {}).id;
let project_ref = '';
const projRaw = String(body.project || body.project_ref || '').trim();
if (projRaw) {
  if (!prjid) return bad('projects table missing (run deploy.mjs)', 'no_projects_table');
  const projects = (await api('GET', '/data-tables/' + prjid + '/rows', { limit: 200 })).data || [];
  const lower = (s) => String(s || '').trim().toLowerCase();
  const proj = projects.find((p) => lower(p.name) === lower(projRaw) || lower(p.label) === lower(projRaw));
  if (!proj) return bad('unknown project: ' + projRaw + ' — register it first (n8n/scripts/seed-projects.mjs)', 'unknown_project');
  if (String(proj.status || 'active') === 'archived') return bad('project is archived: ' + proj.name, 'project_archived');
  project_ref = proj.name;
}
const via = String(body.via || 'api').slice(0, 24);
return [{ json: {
  text, status: 'open', due_date: due, completed_at: '',
  owner_ref,
  project_ref,
  source: via,
  ack_at: '', remind_count: 0, last_remind_at: '', escalated: 0,
  meta: JSON.stringify({ created_at: new Date().toISOString(), via })
} }];

/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* List todos: open (with overdue/due-today flags) + recent done.
   B1: ?owner=<name> filters by assignee; owner=mine|me means unassigned (my own).
   A: ?project=<slug|label> narrows to one project (none = not project work). The
   response carries the registry itself, so a caller can discover valid values
   the same way it discovers people - no extra round trip, no new tool. */
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const id = (tables.find((t) => t.name === 'todos') || {}).id;
if (!id) return [{ json: { ok: false, error: 'todos table missing (run deploy.mjs)' } }];
let rows = (await api('GET', '/data-tables/' + id + '/rows', { limit: 200 })).data || [];

const pid = (tables.find((t) => t.name === 'people') || {}).id;
const people = pid ? ((await api('GET', '/data-tables/' + pid + '/rows', { limit: 200 })).data || []) : [];
const nameOf = (ref) => {
  if (!ref) return '';
  const p = people.find((x) => x.name === ref);
  return p ? (p.display_name || p.name) : ref;
};

const prjid = (tables.find((t) => t.name === 'projects') || {}).id;
const projects = prjid ? ((await api('GET', '/data-tables/' + prjid + '/rows', { limit: 200 })).data || []) : [];
const projName = (ref) => {
  if (!ref) return '';
  const p = projects.find((x) => x.name === ref);
  return p ? (p.label || p.name) : ref;
};

let q = {};
try { q = ($('Webhook List').first().json.query) || {}; } catch (e) { q = {}; }
const ownerFilter = String(q.owner || '').trim().replace(/^@/, '');
if (ownerFilter && (ownerFilter === 'mine' || ownerFilter === 'me')) {
  rows = rows.filter((r) => !(r.owner_ref || ''));
} else if (ownerFilter) {
  rows = rows.filter((r) => (r.owner_ref || '') === ownerFilter);
}

/* ownerFiltered is what the project spread is counted over, so ?project= can
   narrow the list without hiding how the rest of the work is distributed. */
const ownerFiltered = rows;
const projectFilter = String(q.project || '').trim();
const lower = (s) => String(s || '').trim().toLowerCase();
const projMatch = (ref) => {
  const p = projects.find((x) => x.name === ref);
  if (!p) return lower(ref) === lower(projectFilter);
  return lower(p.name) === lower(projectFilter) || lower(p.label) === lower(projectFilter);
};
if (projectFilter && (lower(projectFilter) === 'none' || lower(projectFilter) === 'unassigned')) {
  rows = rows.filter((r) => !(r.project_ref || ''));
} else if (projectFilter) {
  rows = rows.filter((r) => projMatch(r.project_ref || ''));
}

const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
const slim = (r) => ({
  id: r.id, text: r.text, due_date: r.due_date || '',
  owner_ref: r.owner_ref || '', owner_name: nameOf(r.owner_ref),
  project_ref: r.project_ref || '', project_name: projName(r.project_ref),
  overdue: !!(r.due_date && r.due_date < today),
  due_today: !!(r.due_date && r.due_date === today),
});
const open = rows.filter((r) => r.status === 'open').map(slim).sort((a, b) => {
  if (a.due_date && b.due_date) return a.due_date < b.due_date ? -1 : 1;
  if (a.due_date) return -1;
  if (b.due_date) return 1;
  return 0;
});
const done = rows.filter((r) => r.status === 'done').slice(-10).map((r) => ({ id: r.id, text: r.text, completed_at: r.completed_at || '', owner_ref: r.owner_ref || '' }));
const assigned = open.filter((x) => x.owner_ref).length;
const by_project = [];
for (const r of ownerFiltered) {
  if (r.status !== 'open') continue;
  const ref = r.project_ref || '';
  const hit = by_project.find((x) => x.project === ref);
  if (hit) hit.count += 1;
  else by_project.push({ project: ref, label: ref ? projName(ref) : '未归类', count: 1 });
}
by_project.sort((a, b) => b.count - a.count);
return [{ json: {
  ok: true, today,
  open_count: open.length,
  overdue_count: open.filter((x) => x.overdue).length,
  due_today_count: open.filter((x) => x.due_today).length,
  assigned_count: assigned,
  owner_filter: ownerFilter || '',
  project_filter: projectFilter || '',
  projects: projects.filter((p) => String(p.status || 'active') !== 'archived').map((p) => ({ name: p.name, label: p.label || p.name, customer: p.customer || '' })),
  by_project,
  people: people.filter((p) => p.active === 1 || p.active === true).map((p) => ({ name: p.name, display_name: p.display_name || p.name, role: p.role || 'member' })),
  open, done_recent: done,
} }];

/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Validate a todo_done request. */
const body = ($('Webhook Complete').first().json.body) || {};
const id = Number(body.id);
const bad = (m, c) => [{ json: { __error: true, status: 400, body: { error: { message: m, type: 'invalid_request_error', code: c } } } }];
if (!Number.isFinite(id) || id <= 0) return bad('id (number) is required', 'bad_id');
return [{ json: { id } }];

/* Summarize the complete result. */
const rows = $input.all().map((i) => i.json).filter((x) => x && x.id);
if (!rows.length) return [{ json: { ok: false, error: 'todo not found or already done', tip: 'list with GET /webhook/admin/todos' } }];
return [{ json: { ok: true, done: rows.length, todos: rows.map((r) => ({ id: r.id, text: r.text, status: r.status, completed_at: r.completed_at || '' })) } }];
